REVIEW_SCORE = 0.2

def model_cached(mid:str) -> bool:
    "Whether model `mid` is already in the Hugging Face cache, found by scanning the cache and never by downloading."
    try:
        from huggingface_hub import scan_cache_dir
        return any(r.repo_id == mid for r in scan_cache_dir().repos)
    except Exception: return False

@patch
def categorize(self:Vault,
               ref,                # doc_id, source, title, a path on disk, or a loaded `document()`
               model:str=None,     # an id, a path, `mlx/…`; None -> $VISHALAKSHI_MODEL
               chat_kw:dict=None,  # anything else Urai's `Chat` takes: temp, runtime, think, …
               llm:str='auto',     # 'auto' -> only when the cues cannot decide | 'always' | 'never'
               labels:str=None,    # comma-separated labels to choose from; None -> DOCTYPES
               max_chars:int=6000, # chars of the document the model and the cues see
               ner:bool=True,      # run entity extraction alongside the regex signals
               save:bool=True,     # write the verdict into the document's meta
               review:float=REVIEW_SCORE,  # an undecided verdict at or above this is proposed, not written
               pii:str='redact',   # off|local|redact|refuse: what a hosted model gets of a private document, via `send_check`
) -> AttrDict:
    "Decide a document's doctype (invoice, contract, paper and so on) from varga's cues, asking a model only when the cues cannot decide."
    d = (ref if isinstance(ref, dict) and 'text' in ref
         else self.document(ref, max_chars=max(max_chars, 4000)))
    txt = (d.text or '')[:max_chars]
    if not txt.strip():
        return AttrDict(doc_id=d.doc_id, title=d.title, doctype=None, skipped='no text to judge')
    sig = signals(txt, ner=ner)
    g = guess_type(txt, sig, kind=d.kind)
    dt, by = g.doctype, f'cues ({g.method})'
    mode = {True: 'always', False: 'never', None: 'auto'}.get(llm, str(llm).lower())
    assert mode in ('auto', 'always', 'never'), f"llm must be auto, always or never, not {llm!r}"
    if mode == 'always' or (mode == 'auto' and not g.decisive):
        lbls = L(labels.split(',') if isinstance(labels, str) else labels or list(DOCTYPES)).map(str.strip)
        mid = model or dflt_model
        try:
            # auto may use a model already loaded; it must not download one
            if mode == 'auto' and is_stock_chat() and urai().infer_runtime(mid) != 'remote' and not model_cached(mid):
                by = f'cues ({g.method}); {mid or "no model"} is not downloaded, so none was asked'
            else:
                ch = new_chat(mid, **(chat_kw or {}))
                chk = self.send_check(refs=[d.doc_id] if d.doc_id else None, text=None if d.doc_id else txt, model=ch, policy=pii,
                                      level='local' if g.sensitive and g.score >= MIN_SCORE else None)
                it = chk.rows[0]
                if it.how == 'withheld': by = f'cues ({g.method}); the document is {LEVEL_LABELS[it.level]} and {mid} is hosted, so none was asked'
                else:
                    said = ch.classify(f"{d.title}\n\n{txt if it.how == 'whole' else it.get('text') or redact(txt, ner=True)}", list(lbls)+['other'], sp=TYPE_SP)
                    self._sent(chk, mid, getattr(ch, 'runtime', None))
                    if said in lbls or said == 'other': dt, by = said, f'llm ({mid or "Urai default"})'
                    else: by = f'cues ({g.method}); llm answered {said[:40]!r}, not a label'
        except Exception as e:
            # keep the cue verdict when the model leg fails
            if mode == 'always': raise
            by = f'cues ({g.method}); no model available ({type(e).__name__})'
    # a model was asked precisely because the cues could not decide, so its answer is the confident one
    conf = by.startswith('llm') or g.decisive
    res = AttrDict(doc_id=d.doc_id, title=d.title, kind=d.kind, doctype=dt, score=g.score, sensitive=dt in SENSITIVE,
                   margin=g.margin, decisive=g.decisive, confident=conf, by=by, scores=g.scores,
                   signals=sig.counts, ents=sig.ents, saved=False, proposed=False)
    if save and d.doc_id:
        kv = dict(doctype_by=by, doctype_score=g.score)
        if conf: self.set_meta(d.doc_id, doctype=dt, doctype_proposed=None, **kv); res.saved = True
        elif g.score >= review: self.set_meta(d.doc_id, doctype_proposed=dt, **kv); res.proposed = True
    return res

@patch
def categorize_all(self:Vault,
                   kind:str=None,     # restrict to one or more KINDS
                   force:bool=False,  # re-type documents that already carry a doctype
                   limit:int=None,    # stop after this many
                   **kw               # forwarded to categorize (model=, chat_kw=, llm=, ner=, max_chars=)
) -> AttrDict:
    "Categorise every document on this shelf that has no doctype yet, and count the results by doctype."
    docs = self.sources(kind)
    untyped = lambda m: not (m.get('doctype') or m.get('doctype_proposed'))
    if not force: docs = docs.filter(lambda r: untyped(r['meta'] or {}))
    out = L()
    for r in docs[:limit]:
        try: out.append(self.categorize(r['id'], **kw))
        except Exception as e:
            out.append(AttrDict(doc_id=r['id'], title=r['title'], doctype=None,
                                error=f'{type(e).__name__}: {str(e)[:200]}'))
    n_of = lambda k: len(out.filter(lambda o: o.get(k)))
    return AttrDict(n=len(out), typed=n_of('saved'), proposed=n_of('proposed'),
                    by_type=dict(Counter(o.doctype for o in out).most_common()),
                    errors=out.filter(lambda o: o.get('error')), results=out)

@patch
def proposed_types(self:Vault, kind:str=None) -> L:
    "Documents whose doctype is only proposed and waits for a person, surest first."
    p = lambda r: (r['meta'] or {}).get('doctype_proposed')
    return self.sources(kind).filter(p).sorted(key=lambda r: -((r['meta'] or {}).get('doctype_score') or 0))

@patch
def accept_type(self:Vault, ref, doctype:str=None) -> dict:
    "Confirm a document's proposed doctype, or give it `doctype` instead."
    d = self.doc(ref)
    if d is None: raise ValueError(f'no document in the vault matching {ref!r}')
    dt = doctype or (d['meta'] or {}).get('doctype_proposed')
    if not dt: return dict(doc_id=d['id'], title=d['title'], doctype=None, accepted=False)
    self.set_meta(d['id'], doctype=dt, doctype_proposed=None,
                  doctype_by=f"accepted ({(d['meta'] or {}).get('doctype_by') or 'by hand'})")
    return dict(doc_id=d['id'], title=d['title'], doctype=dt, accepted=True)

@patch
def reject_type(self:Vault, ref) -> dict:
    "Drop a document's proposed doctype and leave it untyped."
    d = self.doc(ref)
    if d is None: raise ValueError(f'no document in the vault matching {ref!r}')
    self.set_meta(d['id'], doctype_proposed=None)
    return dict(doc_id=d['id'], title=d['title'], doctype=None, accepted=False)

@patch
def accept_types(self:Vault, k:int=None, kind:str=None) -> L:
    "Confirm the `k` surest waiting proposals, or all of them when `k` is None."
    return self.proposed_types(kind)[:k].map(lambda r: self.accept_type(r['id']))

@patch
def doctypes(self:Vault, kind:str=None) -> dict:
    "Count this shelf's documents by doctype, with `untyped` for those that have none."
    c = Counter((r['meta'] or {}).get('doctype') or 'untyped' for r in self.sources(kind))
    return dict(c.most_common())

@patch
def of_type(self:Vault, doctype:str, kind:str=None) -> L:
    'Every document categorised as `doctype`, newest first.'
    return self.sources(kind).filter(lambda r: (r['meta'] or {}).get('doctype') == doctype)

# doctype routing (KIND_SHELF is arrival kind)
DOCTYPE_SHELF = {'paper': 'papers', 'code': 'code', 'catalogue': 'data'}

@patch
def reshelf(self:Vault,
            ref,                      # doc_id, source, or a title substring
            shelf:str=None,           # where to put it; None -> whatever its doctype says
            llm:str='auto',           # the LLM leg of the categorisation that picks the shelf
            max_chars:int=2_000_000,  # cap on the text carried over
            **kw                      # forwarded to categorize (model=, chat_kw=, ner=)
) -> AttrDict:
    "Move a document to `shelf`, or to the shelf its doctype belongs on: papers to `papers`, code to `code`, catalogues to `data`."
    d = self.document(ref, max_chars=max_chars)
    c = self.categorize(d, save=False, llm=llm, **kw) if shelf is None else None
    nm = shelf or (DOCTYPE_SHELF.get(c.doctype) if c.confident else None)
    out = AttrDict(doc_id=d.doc_id, title=d.title, doctype=c.doctype if c else None,
                   was=self.name, store=self.name, moved=False)
    if c is not None and not c.confident: out.skipped = 'the doctype is a guess, not a verdict'
    if not nm or nm == self.name or not d.doc_id: return out
    r = self.shelf(nm).add(d.text, d.title, source=d.source, kind=d.kind, force=True,
                           meta=dict(d.meta, doctype=out.doctype, reshelved_from=self.name))
    self.forget(d.doc_id)
    return AttrDict(out, doc_id=r.get('doc_id'), store=nm, moved=True, chunks=r.get('chunks'))

@patch
def ner(self:Vault,
        ref:str,              # doc_id, source, title substring, or a path on disk
        limit:int=40,         # entities returned
        max_chars:int=20000,
) -> AttrDict:
    "List the entities one document names, such as organisations, people, places and products, with their counts."
    d = self.document(ref, max_chars=max_chars)
    sig = signals(d.text, limit=limit)
    return AttrDict(doc_id=d.doc_id, title=d.title, method=sig.method, counts=sig.counts,
                    labels=sig.labels, ents=sig.ents)


